import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.json.*;

@WebServlet("/api/users/*")
public class UserSearchServlet extends HttpServlet {

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String pathInfo = req.getPathInfo();
        resp.setContentType("application/json");

        if (pathInfo != null && pathInfo.equals("/search")) {
            handleSearch(req, resp);
        } else if (pathInfo != null && pathInfo.equals("/profile")) {
            handleProfile(req, resp);
        } else {
            resp.setStatus(404);
            resp.getWriter().write("{\"error\":\"not found\"}");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String department = req.getParameter("dept");
        String role = req.getParameter("role");

        // Build filter - department is validated against enum
        String[] validDepts = {"engineering", "sales", "marketing", "hr", "finance"};
        boolean validDept = false;
        for (String d : validDepts) {
            if (d.equals(department)) { validDept = true; break; }
        }

        if (!validDept) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid department\"}");
            return;
        }

        // Role parameter is used in query construction
        // Developer note: role comes from internal dropdown, should be safe
        String query = "SELECT id, name, email, department, role FROM users " +
                       "WHERE department = '" + department + "' " +
                       "AND role = '" + role + "'";

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject user = new JSONObject();
                user.put("id", rs.getInt("id"));
                user.put("name", rs.getString("name"));
                user.put("email", rs.getString("email"));
                user.put("department", rs.getString("department"));
                user.put("role", rs.getString("role"));
                results.put(user);
            }
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"query failed: " + e.getMessage() + "\"}");
        }
    }

    private void handleProfile(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String userId = req.getParameter("id");

        // Validate numeric ID
        if (userId == null || !userId.matches("^[0-9]+$")) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid id\"}");
            return;
        }

        String query = "SELECT id, name, email, department, role, phone FROM users WHERE id = " + userId;

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            if (rs.next()) {
                JSONObject user = new JSONObject();
                user.put("id", rs.getInt("id"));
                user.put("name", rs.getString("name"));
                user.put("email", rs.getString("email"));
                user.put("department", rs.getString("department"));
                user.put("role", rs.getString("role"));
                user.put("phone", rs.getString("phone"));
                resp.getWriter().write(user.toString());
            } else {
                resp.setStatus(404);
                resp.getWriter().write("{\"error\":\"user not found\"}");
            }
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"query failed\"}");
        }
    }
}
